// 클래스 정의
public class Car {
    String brand;  // 속성(필드)
    int speed;

    // 메서드
    void accelerate() {
        speed += 10;
        System.out.println(brand + " 속도: " + speed);
    }
}

// 객체 생성 및 사용
public class Main {
    public static void main(String[] args) {
        Car myCar = new Car();  // 객체 생성
        myCar.brand = "현대";
        myCar.accelerate();  // 현대 속도: 10
    }
}

public class Person {
    String name;
    int age;

    // 생성자
    public Person(String name, int age) {
        this.name = name;  // this.name = 필드, name = 매개변수
        this.age = age;
    }

    void introduce() {
        System.out.println("이름: " + this.name + ", 나이: " + this.age);
    }
}

// 사용
Person p = new Person("김철수", 20);
p.introduce();  // 이름: 김철수, 나이: 20

// 부모 클래스
public class Animal {
    String name;

    void speak() {
        System.out.println(name + "이 소리를 냅니다");
    }
}

// 자식 클래스 (상속)
public class Dog extends Animal {

    @Override
    void speak() {
        System.out.println(name + ": 멍멍!");  // 오버라이딩
    }

    void fetch() {
        System.out.println(name + "이 공을 가져옵니다");
    }
}

// 사용
Dog dog = new Dog();
dog.name = "바둑이";  // 부모 필드 사용
dog.speak();   // 바둑이: 멍멍!
dog.fetch();   // 바둑이이 공을 가져옵니다

public class Animal {
    void speak() { System.out.println("..."); }
}

public class Dog extends Animal {
    @Override
    void speak() { System.out.println("멍멍!"); }
}

public class Cat extends Animal {
    @Override
    void speak() { System.out.println("야옹!"); }
}

// 다형성 활용
Animal[] animals = {
    new Dog(),
    new Cat(),
    new Dog()
};

for (Animal a : animals) {
    a.speak();  // 각각 다르게 동작
}
// 멍멍!
// 야옹!
// 멍멍!

// 인터페이스 정의
public interface Flyable {
    void fly();  // 추상 메서드
}

public interface Swimmable {
    void swim();
}

// 다중 인터페이스 구현
public class Duck implements Flyable, Swimmable {

    @Override
    public void fly() {
        System.out.println("오리가 날아갑니다");
    }

    @Override
    public void swim() {
        System.out.println("오리가 수영합니다");
    }
}

// 사용
Duck duck = new Duck();
duck.fly();   // 오리가 날아갑니다
duck.swim();  // 오리가 수영합니다
